package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import dao.OrdenPagoDAO;import negocio.*;import pagos.*;
class WebhookMercadoPagoServiceTest {@Test void validaFinanzasYDelegaAcreditacion(){OrdenPagoDAO d=mock(OrdenPagoDAO.class);PasarelaPagoOnline p=mock(PasarelaPagoOnline.class);AcreditacionOrdenPagoTransaccionalService a=mock(AcreditacionOrdenPagoTransaccionalService.class);OrdenPago o=new OrdenPago();o.setId(4);o.setProveedor(ProveedorPago.MERCADO_PAGO);o.setReferenciaExterna("orden:9");o.setImporte(new BigDecimal("6250.00"));o.setMoneda("ARS");when(p.consultarPago("123")).thenReturn(new PagoExterno("123","orden:9","approved","accredited",new BigDecimal("6250"),"ARS",null));when(d.buscarPorPagoExterno(any(),any())).thenReturn(null);when(d.buscarPorReferencia(ProveedorPago.MERCADO_PAGO,"orden:9")).thenReturn(o);when(a.procesarAprobacion(any(),eq("123"))).thenReturn(true);var r=new WebhookMercadoPagoService(d,p,a).procesar("123","{}");assertTrue(r.aprobado());assertTrue(r.procesado());verify(d).asociarPagoExterno(4,"123");}@Test void rechazaImporteDistinto(){OrdenPagoDAO d=mock(OrdenPagoDAO.class);PasarelaPagoOnline p=mock(PasarelaPagoOnline.class);OrdenPago o=new OrdenPago();o.setId(4);o.setProveedor(ProveedorPago.MERCADO_PAGO);o.setReferenciaExterna("orden:9");o.setImporte(new BigDecimal("6250"));o.setMoneda("ARS");when(p.consultarPago("123")).thenReturn(new PagoExterno("123","orden:9","approved","x",new BigDecimal("1"),"ARS",null));when(d.buscarPorReferencia(any(),any())).thenReturn(o);assertThrows(WebhookMercadoPagoService.ConflictoPagoException.class,()->new WebhookMercadoPagoService(d,p,mock(AcreditacionOrdenPagoTransaccionalService.class)).procesar("123","{}"));}}
